-- Applies only the settings explicitly approved by the Site owner on 2026-09-12.
-- Preserve other settings, application records, previous consent and credentials.
-- With no settings row, the same approved values are configured in Sites env.
UPDATE site_settings
SET values_json=json_patch(values_json, '{"DATA_CONTROLLER_NAME":"Partido Acción Nacional","DATA_CONTROLLER_ADDRESS":"Calle Metepec 33, colonia La Romana, Tlalnepantla de Baz, Estado de México, C.P. 54030, México","ARCO_EMAIL":"socios@millabogados.com","DATA_CONTROLLER_REGIME":"party","DATA_CONTROLLER_LEGAL_BASIS":"Los artículos 2, incisos a), c) e i); 15, numeral 2, incisos a) y c); y 84, incisos c), e) y o), de los Estatutos del Partido Acción Nacional contemplan sus actividades de formación y organización, la atención electrónica a simpatizantes y las atribuciones municipales para integrar comisiones, aprobar actividades y establecer mecanismos de comunicación. Este registro se limita a recibir y dar seguimiento a solicitudes internas. No realiza el procedimiento de afiliación previsto en el artículo 9.","TRANSPARENCY_ADDRESS":"Boulevard Toluca número 03, Fraccionamiento Industrial Naucalpan, Naucalpan de Juárez, Estado de México, C.P. 53370","RIGHTS_PROCEDURE":"Puedes presentar una solicitud de acceso, rectificación, cancelación u oposición ante la Unidad de Transparencia del PAN Estado de México, en el domicilio indicado en este aviso. El correo socios@millabogados.com recibe las consultas de privacidad y coordina su atención con esa Unidad. Indica tu nombre, un medio para recibir notificaciones, lo que solicitas y, si lo tienes, el folio del expediente. Deberás acreditar tu identidad y, en su caso, la representación por el medio que se te indique. No envíes identificaciones completas en el primer mensaje. La respuesta se emitirá en un máximo de veinte días hábiles, prorrogables una sola vez hasta por diez días mediante justificación y aviso. Si procede, el derecho se hará efectivo dentro de los quince días hábiles siguientes a la notificación. La misma vía permite solicitar la revocación del consentimiento o la limitación del uso de tus datos, sin afectar la licitud del tratamiento realizado con anterioridad.","PRIVACY_NOTICE_VERSION":"registro-2026-09-12.2","MEMBERSHIP_RETENTION_DAYS":"90","MEMBERSHIP_DIRECT_CONSENT":"1","MEMBERSHIP_NOTICE_APPROVED":"1","MEMBERSHIP_ENABLED":"1"}'),
    updated_at=max(updated_at+1, CAST(strftime('%s','now') AS INTEGER)*1000),
    updated_by='system:owner-authorized-deployment'
WHERE id='public' AND json_valid(values_json) AND json_type(values_json)='object';
