INSERT INTO audit_logs(id,actor_email,action,entity_type,entity_id,metadata_json,created_at)
SELECT 'approved-notice-2026-09-12', 'system:owner-authorized-deployment',
       'settings.approved_notice_deployment', 'settings', 'public', '{"authorization":"Site owner confirmed the proposal and opening in conversation on 2026-09-12","changedFields":["DATA_CONTROLLER_NAME","DATA_CONTROLLER_ADDRESS","ARCO_EMAIL","DATA_CONTROLLER_REGIME","DATA_CONTROLLER_LEGAL_BASIS","TRANSPARENCY_ADDRESS","RIGHTS_PROCEDURE","PRIVACY_NOTICE_VERSION","MEMBERSHIP_RETENTION_DAYS","MEMBERSHIP_DIRECT_CONSENT","MEMBERSHIP_NOTICE_APPROVED","MEMBERSHIP_ENABLED"]}',
       CAST(strftime('%s','now') AS INTEGER)*1000
FROM site_settings
WHERE id='public' AND updated_by='system:owner-authorized-deployment'
  AND json_extract(values_json, '$.PRIVACY_NOTICE_VERSION')='registro-2026-09-12.2';
